std::string hex(const std::string& value) {
    static const char* digits = "0123456789abcdef";
    std::string result;
    for (unsigned char c : value) {
        result += digits[c >> 4]; result += digits[c & 15];
    }
    return result;
}

class Probe final : public dx_iface {
public:
    std::vector<std::pair<const char*, std::uint32_t>> inheritedDefaults;
    std::vector<DRW_DictionaryWithDefault> dictionaryDefaults;
    void addDictionaryWithDefault(const DRW_DictionaryWithDefault& o) override {
        inheritedDefaults.emplace_back("DICTIONARYWDFLT", o.handle);
        dictionaryDefaults.push_back(o);
        dx_iface::addDictionaryWithDefault(o);
    }
    void addAcDbPlaceholder(const DRW_AcDbPlaceholder& o) override {
        inheritedDefaults.emplace_back("ACDBPLACEHOLDER", o.handle);
